import { v4 as uuidv4 } from "uuid";

type Callback = {
  resolve: (value: any) => void;
  reject: (reason?: any) => void;
  timeoutId: NodeJS.Timeout;
};

const DEFAULT_TIMEOUT_MS = 10*60*1000; // 10 mins timeout

class MessageCallbackStore {
	private callbacks = new Map<string, Callback>()

	public addCallback(resolve: (value: any) => void, reject: (reason?: any) => void, timeoutMs: number = DEFAULT_TIMEOUT_MS): string {
		const id = uuidv4()
		
		// Set up timeout to automatically reject if no response received
		const timeoutId = setTimeout(() => {
			const callback = this.callbacks.get(id)
			if (callback) {
				callback.reject(new Error(`Message callback timed out after ${timeoutMs}ms`))
				this.callbacks.delete(id)
			}
		}, timeoutMs)
		
		this.callbacks.set(id, { resolve, reject, timeoutId })
		return id
	}

	public resolveCallback(id: string, result: any) {
		const callback = this.callbacks.get(id)
		if (callback) {
			clearTimeout(callback.timeoutId)
			callback.resolve(result)
			this.callbacks.delete(id)
		}
	}

	public rejectCallback(id: string, reason: string) {
	   const error = new Error(reason)
	   const callback = this.callbacks.get(id)
		if (callback) {
	     clearTimeout(callback.timeoutId)
	     callback.reject(error)
	     this.callbacks.delete(id)
		}
	}
}

export const messageCallbackStore = new MessageCallbackStore();
